%[text] # von Mises kappa and the Phase Locking Value/Pairwise Phase Consistency
%[text] Simulates spikes with a range of von Mises kappa synchrony parameters and computes the PPC. Generates a plot to show the relation between the two. The goal is to get an intuitive idea of their relation, which makes chosing a kappa for the simulations easier.
o=artSim;
o.duration =  60*2; % [s] 
o.spikeRate = 100;  
o.spikePeak = 100e-6;
o.refractoryPeriod = 1.5e-3;
o.recordingSamplingRate = 30e3;
o.lfpAmplitude = 5e-6;
o.lfpFrequency = 10;
o.preferredPhase = 0.5*pi;
o.poisson  = true;
%%
%[text] ## Run simulation
kappa =[0:0.1:1 1.5:0.5:5];
nrKappa = numel(kappa);
nrBootstraps = 100;
ppcValue= nan(nrKappa,nrBootstraps);
for k=1:nrKappa
    o.synchrony = kappa(k);
    for bs=1:nrBootstraps
        o.simLfp;
        o.simSpikes;
        [ppcValue(k,bs)] = ppc(o.ixSpike,o.phaseLfp);
    end
end
%%
%[text] ## Generate figure
fig('Name','KappaPLV','nrRows',1,'nrCols',1); %[output:972fa61f]
yyaxis left %[output:972fa61f]
errorbar(kappa,mean(ppcValue,2)',std(ppcValue,0,2)','b'); %[output:972fa61f]
ylabel 'PPC' %[output:972fa61f]
yyaxis right %[output:972fa61f]
ppcValue(ppcValue<0)=0;%Upward bias, but good enough
errorbar(kappa,mean(sqrt(ppcValue),2)',std(sqrt(ppcValue),0,2)','r'); %[output:972fa61f]
ylabel 'PLV' %[output:972fa61f]
xlabel 'Von Mises Kappa' %[output:972fa61f]

